        const maskInfo = ctx.maskInfo || {};
        const obstacles = this.getObstacles();
        const denseUrban = !!ctx.denseUrban || this.isDenseUrbanContext(ctx.arenaMode, obstacles);
        const brakeTurnMemory = this.getBrakeTurnMemory(teamId);
