                const altitudeBand = this.getCombatAltitudeProfile(altitude, tuning, selfForward.y);
                        tree.push(`altitudeBandGate: zone=${altitudeBand.zone} excess=${altitudeBand.excess.toFixed(1)} fwdY=${selfForward.y.toFixed(2)}`);
